/* ============ Arkaden: hallen med de fem maskiner. Bank en gnom kan spilles; de andre åbner senere ============ */
ROOMS.arkade=function(ctx){
  const M=[{id:'gnom',navn:'Bank en gnom',x:-34,rum:'gnom'},{id:'skjold',navn:'Stjerneskjoldet',x:-15,body:'#3a4aa8',trim:'#7fd8ff'},{id:'invader',navn:'Hekse-invaders',x:1,body:'#7a2a8a',trim:'#ff8fc7'},{id:'tryl',navn:'Trylletegning',x:17,body:'#2a1c78',trim:'#ffd86b'},{id:'gribe',navn:'Gribemaskinen',x:35}];
  const P2=(g,shape,o,z)=>put(g,piece(shape,o),0,0,z),W0={x:-8,tx:-8,ph:0,amp:0,face:1,want:null};let heks,kat,gone=false;
  const hit=(g,m,w,h,y)=>{const hb=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({visible:false}));hb.position.set(m.x,y,-2);g.add(hb);Rm.tap(hb,()=>{W0.tx=m.x+(m.x>0?-9:9)*(m.rum?0:0)+0;W0.want=m})};
  const Rm=makeRoom(ctx,{bg:'#0c0816',fit:fitBox(90,50,0,20.5),sky:'#b0a0ff',ground:'#2a2040',amb:.38,key:{col:'#e8d8ff',i:1.4,tgt:[0,16,0]},
    build:Rm=>[()=>{const g=Rm.scene,W=box(-76,-2,76,64);
        P2(g,W,{t:.5,s:9,cap:1800,paint:P=>{P.wash('#2a1c4a',W,{top:'#160e2c',edge:0,clouds:14});for(let i=0;i<70;i++)P.fill(starPts(R(-76,76),R(12,64),R(.3,.7),.2,R(1)),['#ff8fc7','#7fd8ff','#ffd86b'][i%3],R(.35,.8));P.wash('#120a22',box(-77,-3,77,10),{alpha:.96,edge:0,mode:'source-over'})}},-10);
        for(let i=0;i<14;i++)for(let j=0;j<5;j++)Rm.floor(box(-78+i*11.2,-10+j*8.2,-66.8+i*11.2,-1.8+j*8.2),{color:(i+j)%2?'#2a2044':'#4a3a7a',kind:'water',t:.3},0);
        /* neonskilt over maskinerne */
        plate(g,'arkade','ARKADEN',FONT.arkade,30,5.2,{bg:'#160e2c',frame:'gold',size:3.4,fg:'#ffd86b',y:39.4,z:-9});Rm.glow(0,42,-7,'#ffd86b',34);for(const[x,c]of[[-30,'#ff8fc7'],[30,'#7fd8ff']]){P2(g,starPts(x,42,3,1.3),{t:.3,mat:paperMat('#ffffff','tissue',{glow:c,gi:1.7})},-9);Rm.glow(x,42,-7.6,c,13)}},
      ()=>{const g=Rm.scene;/* de tre skærmmaskiner */
        for(const m of M.filter(m=>m.body)){const x=m.x,bd=sm([[x-6,0,1],[x+6,0,1],[x+6,12,1],[x+5,16],[x+5,29,1],[x+6.4,31],[x+6.4,35,1],[x-6.4,35,1],[x-6.4,31],[x-5,29,1],[x-5,16],[x-6,12,1]],4);
          P2(g,bd,{t:1.2,s:18,paint:P=>{P.wash(m.body,bd,{top:hexOf(shade(m.body,.2)),edge:.6,clouds:5});for(let i=0;i<8;i++)P.fill(starPts(x+R(-5,5),R(1,11),.4,.17,R(1)),m.trim,.8);P.pen([[x-5.6,.6],[x-5.6,11.6]],m.trim,.14,.8);P.pen([[x+5.6,.6],[x+5.6,11.6]],m.trim,.14,.8)}},-7);
          P2(g,box(x-4.3,17.6,x+4.3,28),{t:.1,mat:paperMat('#101828','tissue',{glow:m.trim,gi:.55})},-6.3);
          if(m.id==='skjold'){for(const q of ring(circ(x,22.6,2.9,2.9,24),.4,false))P2(g,q,{t:.06,mat:paperMat('#ffffff','tissue',{glow:m.trim,gi:1.6})},-6.2);P2(g,starPts(x,22.6,1.7,.75),{t:.06,mat:paperMat('#fff6c0','tissue',{glow:'#ffd86b',gi:1.6})},-6.15)}
          if(m.id==='invader'){for(let r=0;r<2;r++)for(let c=0;c<4;c++)P2(g,box(x-3.4+c*1.9,25-r*1.9,x-2.2+c*1.9,26-r*1.9),{t:.05,mat:paperMat('#ffffff','tissue',{glow:r?'#7fd8ff':m.trim,gi:1.6})},-6.2);P2(g,toCCW([[x-1,18.6],[x+1,18.6],[x,20.4]]),{t:.05,mat:paperMat('#ffffff','tissue',{glow:'#ffd86b',gi:1.6})},-6.2)}
          if(m.id==='tryl'){for(const q of thick([curve([[x-3,20],[x-1.6,25.6],[x,21.4],[x+1.6,25.6],[x+3,20]],10)],.3))P2(g,q,{t:.05,mat:paperMat('#ffffff','tissue',{glow:m.trim,gi:1.7})},-6.2)}
          Rm.glow(x,23,-5,m.trim,15);P2(g,toCCW([[x-5.4,12.4],[x+5.4,12.4],[x+4.6,16.4],[x-4.6,16.4]]),{color:'#1c1430',kind:'water',t:1.6},-6);for(const s of thick([[[x-2.2,14.4],[x-2.2,17]]],.24))P2(g,s,{color:'#d8d8e8',t:.3},-4.4);P2(g,circ(x-2.2,17.2,.6,.6,12),{color:'#e04a5a',kind:'water',t:.5},-4.4);for(const[dx,c]of[[1,'#ffd86b'],[2.8,'#7fd8ff']])P2(g,circ(x+dx,14.6,.55,.4,12),{color:c,kind:'water',t:.4},-4.3);
          plate(g,m.id,m.navn,FONT.arkade,11.6,2.5,{bg:'#160e2c',fg:m.trim,size:1.15,x,y:31.8,z:-5.7});hit(g,m,14,36,18)}},
      ()=>{const g=Rm.scene;/* Bank en gnom: et bord med huller. Gribemaskinen: en glaskasse med bamser */
        {const m=M[0],x=m.x,bd=box(x-8,0,x+8,11);P2(g,bd,{t:1.4,s:16,paint:P=>{P.wash('#3f7a4a',bd,{top:'#5a9a5a',edge:.5,clouds:5});for(let i=0;i<10;i++)P.fill(starPts(x+R(-7,7),R(1,10),.4,.17,R(1)),'#ffd86b',.8)}},-7);P2(g,toCCW([[x-8.6,11],[x+8.6,11],[x+7.4,16],[x-7.4,16]]),{color:'#5aa85a',kind:'water',t:6},-9.6);
          for(const[dx,dy]of[[-4.6,12.6],[0,12.2],[4.6,12.6]])P2(g,circ(x+dx,dy+.6,1.7,.7,16),{color:'#1c1410',t:.1},-3.2+dy*.0);
          const gx=x,gy=13.2;P2(g,circ(gx,gy+1.4,1.3,1.3,16),{color:'#f2c8a0',kind:'water',t:.3},-3);P2(g,toCCW([[gx-1.5,gy+2.2],[gx+1.5,gy+2.2],[gx+.3,gy+5.6]]),{color:'#d8402a',kind:'water',t:.3},-2.9);P2(g,sm([[gx-1.3,gy+1.2],[gx+1.3,gy+1.2],[gx+.9,gy-.4],[gx,gy-1],[gx-.9,gy-.4]],4),{color:'#f6f0e2',kind:'water',t:.3},-2.8);
          P2(g,box(x-8.6,19,x+8.6,29),{color:'#2f5a3a',kind:'water',t:1},-9.2);plate(g,m.id,m.navn,FONT.arkade,13,2.8,{bg:'#160e2c',fg:'#9be36a',size:1.25,x,y:22.6,z:-8.2});Rm.glow(x,24,-6,'#9be36a',16);hit(g,m,18,30,15)}
        {const m=M[4],x=m.x;P2(g,box(x-7,0,x+7,13),{t:1.2,s:16,paint:P=>{P.wash('#b83a6a',null,{edge:.5,top:'#d85a8a'});for(let i=0;i<8;i++)P.fill(starPts(x+R(-6,6),R(1,12),.4,.17,R(1)),'#ffd86b',.8)}},-7);P2(g,box(x-6.6,13,x+6.6,31),{t:.1,mat:paperMat('#c8e8ff','tissue',{glow:'#9fd8ff',gi:.35})},-8.6);
          for(const[dx,dy,c]of[[-3.6,14.6,'#b5743a'],[0,14.4,'#f7f4ff'],[3.6,14.8,'#7ac86a'],[-1.8,17.4,'#ff9fd0'],[2,17.6,'#9c6a48']]){P2(g,circ(x+dx,dy+1.2,1.7,1.6,16),{color:c,kind:'water',t:.4},-7.6);for(const s of[-1,1])P2(g,circ(x+dx+s*1.2,dy+2.6,.6,.6,10),{color:c,kind:'water',t:.4},-7.7);for(const s of[-1,1])P2(g,circ(x+dx+s*.55,dy+1.5,.16,.16,8),{color:'#1c1410',t:.1},-7.3)}
          for(const s of thick([[[x+1,31],[x+1,25]]],.2))P2(g,s,{color:'#d8d8e8',t:.2},-7.4);for(const s of[-1,1])for(const q of thick([[[x+1,25],[x+1+s*1.4,23.4],[x+1+s*.7,22.2]]],.18))P2(g,q,{color:'#d8d8e8',t:.2},-7.4);
          for(const dx of[-7,6.2])P2(g,box(x+dx,13,x+dx+.8,31.8),{color:'#8a2a4a',kind:'water',t:1.6},-7.6);P2(g,box(x-7.4,31,x+7.4,35),{color:'#b83a6a',kind:'water',t:1.6},-7.6);plate(g,m.id,m.navn,FONT.arkade,12.6,2.5,{bg:'#160e2c',fg:'#ff8fc7',size:1.15,x,y:31.8,z:-6.2});Rm.glow(x,22,-6,'#9fd8ff',16);hit(g,m,16,36,18)}},
      ()=>{heks=makeFigure(Object.assign({},ctx.look));heks.G.scale.setScalar(.8);heks.G.position.set(W0.x,.35,6);Rm.live.add(heks.G);W0.sh=Rm.blob(W0.x,6,13,5);kat=makeCat();kat.G.scale.setScalar(.5);kat.G.position.set(-16,.35,8);Rm.live.add(kat.G);ctx.say('Tryk på en maskine')}],
    tick:(t,dt)=>{const d=W0.tx-W0.x,mv=Math.abs(d)>.3;if(mv){const st=Math.sign(d)*Math.min(Math.abs(d),26*dt);W0.x+=st;W0.face=Math.sign(d);W0.ph+=Math.abs(st)/3.4*Math.PI}
      W0.amp+=((mv?1:0)-W0.amp)*Math.min(1,dt*8);heks.G.position.x=W0.x;heks.G.scale.x=.8*W0.face;heks.G.position.y=.35+Math.abs(Math.sin(W0.ph))*.5*W0.amp;heks.tick(t,{ph:W0.ph,amp:W0.amp});W0.sh.position.x=W0.x;
      const kx=W0.x-W0.face*8,kd=kx-kat.G.position.x,km=Math.abs(kd)>.6;if(km)kat.G.position.x+=Math.sign(kd)*Math.min(Math.abs(kd),28*dt);kat.G.scale.x=.5*(km?Math.sign(kd):W0.face);kat.tick(t,{ph:t*13,amp:km?1:0});
      if(W0.want&&!mv&&!gone){const m=W0.want;W0.want=null;if(m.rum&&ROOMS[m.rum]){gone=true;ctx.go(m.rum)}else ctx.say(`${m.navn} åbner snart`)}}})};

/* ============ Bank en gnom: gnomerne stikker hovedet op af hullerne; ram så mange som muligt, før tiden løber ud ============ */
ROOMS.gnom=function(ctx){
  const P2=(g,shape,o,z)=>put(g,piece(shape,o),0,0,z),ROWS=[{y:27,z:-6,xs:[-24,0,24]},{y:15.5,z:0,xs:[-33,-11,11,33]},{y:4,z:6,xs:[-24,0,24]}],G=[],TID=30;let sc=0,left=TID,on=false,next=0,bc,bt,over=false;
  const tavle=()=>{const g=bc.getContext('2d');g.fillStyle='#160e2c';g.fillRect(0,0,768,128);g.fillStyle='#9be36a';g.textAlign='center';g.textBaseline='middle';g.font='400 64px "Rye",Georgia,serif';g.fillText(on?`Ramt ${sc}  ·  ${Math.ceil(left)} sek.`:over?`Du ramte ${sc}!  Tryk for at spille igen`:'Tryk for at begynde',384,68,740);bt.needsUpdate=true};
  const begynd=()=>{sc=0;left=TID;on=true;over=false;next=.5;tavle()};
  const Rm=makeRoom(ctx,{bg:'#0c1410',fit:fitBox(90,50,0,22),sky:'#c8f0d0',ground:'#2a3a2a',amb:.55,key:{col:'#fff2d0',i:1.9,tgt:[0,16,0]},miss:()=>{if(!on)begynd()},
    build:Rm=>[()=>{const g=Rm.scene,W=box(-76,-2,76,66);P2(g,W,{t:.5,s:9,cap:1800,paint:P=>{P.wash('#2a4a5a',W,{top:'#16283a',edge:0,clouds:14});for(let i=0;i<60;i++)P.fill(starPts(R(-76,76),R(30,66),R(.25,.6),.2,R(1)),'#f6e7c0',R(.3,.8))}},-12);
        P2(g,box(-17,43.4,17,50),{color:'#2a1c4a',kind:'water',t:.8},-10);for(const x of[-21,21]){P2(g,starPts(x,46.6,2.6,1.1),{t:.3,mat:paperMat('#ffffff','tissue',{glow:'#ffd86b',gi:1.7})},-10);Rm.glow(x,46.6,-8,'#ffd86b',11)}},
      ()=>{const lv=Rm.live;/* tre græsvolde i det levende lag: gnomerne gemmer sig bag dem */
        ROWS.forEach((r,ri)=>{const top=[];for(let i=0;i<=24;i++){const x=-60+i*5;top.push([x,r.y+1.2+Math.sin(i*1.3+ri*2)*.7])}const sh=toCCW([[-60,r.y-13],[60,r.y-13],...top.reverse()]),c=['#3f7a4a','#4a8a52','#57a05c'][ri];
          const m=piece(sh,{t:.6,s:10,cap:1400,paint:P=>{P.wash(c,sh,{top:hexOf(shade(c,.22)),edge:.5,clouds:10});for(let i=0;i<90;i++){const x=R(-58,58),y=R(r.y-12,r.y);P.pen([[x,y],[x+R(-.3,.3),y+R(.6,1.2)]],hexOf(shade(c,-.25)),.08,.6)}for(const x of r.xs){P.fill(circ(x,r.y+.2,4.6,2.6,24),'#14100c',.92)}for(let i=0;i<8;i++){const x=R(-56,56),y=R(r.y-11,r.y-3);P.fill(circ(x,y,.5,.5,8),['#ff9ad0','#ffe27a','#f6f6ff'][i%3],.9)}}});m.position.z=r.z+.6;m.userData.noShadow=false;lv.add(m);
          r.xs.forEach(x=>{const g=new THREE.Group(),hat=['#d8402a','#2f6fb0','#e0a020','#7a3fa2'][G.length%4];g.position.set(x,r.y-16.5,r.z);lv.add(g);
            P2(g,sm([[-3.2,0],[3.2,0],[3.4,5],[-3.4,5]],3),{color:hexOf(shade(hat,-.25)),kind:'water',t:.3},0);P2(g,circ(0,6.6,2.9,2.7,24),{color:'#f2c8a0',kind:'water',t:.3},.1);P2(g,sm([[-2.9,6.2],[2.9,6.2],[2.2,2.4],[0,.8],[-2.2,2.4]],5),{color:'#f6f0e2',kind:'water',t:.3},.3);P2(g,circ(0,6.3,.8,.7,12),{color:'#e8a080',kind:'water',t:.3},.5);
            for(const s of[-1,1])P2(g,circ(s*1.1,7.3,.3,.36,10),{color:'#1c1410',t:.1},.45);P2(g,toCCW(sm([[-3.3,8.4,1],[3.3,8.4,1],[1.2,12.6],[.2,15.6,1],[-.9,12.4]],5)),{color:hat,kind:'water',t:.3},.2);P2(g,box(-3.3,8.2,3.3,9),{color:'#f6e7c0',kind:'water',t:.34},.3);
            const o={g,x,y0:r.y-16.5,up:0,want:0,t:0,hit:0};G.push(o);const hb=new THREE.Mesh(new THREE.PlaneGeometry(9,13),new THREE.MeshBasicMaterial({visible:false}));hb.position.set(0,7,.8);g.add(hb);
            Rm.tap(hb,()=>{if(!on){begynd();return}if(o.up>.45&&!o.hit){o.hit=1;o.want=0;sc++;tavle();Rm.burst(x,r.y+6,r.z+3,9,'rgba(255,236,170,.95)',5)}})})});
        bc=cv(768,128);bt=tx(bc,true);const bm=new THREE.Mesh(new THREE.PlaneGeometry(32,5.33),new THREE.MeshBasicMaterial({map:bt,toneMapped:false}));bm.position.set(0,46.7,-9.4);bm.userData.noShadow=true;lv.add(bm);tavle();ctx.say('Ram gnomerne, når de stikker hovedet op!')}],
    tick:(t,dt)=>{if(on){left-=dt;if(Math.ceil(left)!==Math.ceil(left+dt))tavle();next-=dt;if(next<=0){const fri=G.filter(o=>o.want===0&&o.up<.05);if(fri.length){const o=fri[Math.floor(Math.random()*fri.length)];o.want=1;o.hit=0;o.t=.7+Math.random()*.9*(left/TID+.35)}next=.28+Math.random()*.5*(left/TID+.3)}
        if(left<=0){on=false;over=true;for(const o of G)o.want=0;const stj=Math.min(5,Math.floor(sc/4));if(stj)SPIL.giv(stj);tavle();ctx.say(stj?`Du ramte ${sc} gnomer og fik ${stj} ${stj===1?'stjerne':'stjerner'}!`:`Du ramte ${sc} gnomer. Prøv igen, så går det bedre!`)}}
      for(const o of G){if(o.want){o.t-=dt;if(o.t<=0)o.want=0}o.up+=((o.want?1:0)-o.up)*Math.min(1,dt*(o.want?14:9));const sq=o.hit?Math.max(.55,1-o.hit*.45):1;o.hit=Math.max(0,o.hit-dt*1.5)||(o.hit&&.001);o.g.position.y=o.y0+o.up*15.2;o.g.scale.set(2-sq,sq,1)}}});
  ctx.test={start:begynd,state:()=>({sc,left:Math.round(left),on,over}),hitAll:()=>{for(const o of G)if(o.up>.45&&!o.hit){o.hit=1;o.want=0;sc++}tavle()}}};
